            var r=new BattleBuild.Report{passed=true,unityVersion=Application.unityVersion};Action<string,Action> check=(id,a)=>{try{a();r.checks.Add(new BattleBuild.Check{id=id,result="pass"});}catch(Exception ex){r.passed=false;r.checks.Add(new BattleBuild.Check{id=id,result="fail",detail=ex.ToString()});}};
            check("source-item-manager-original-record-local-restart-and-login-gate",()=>{var f=new Fixture();f.Global.Indexes.Items[8001]=new OutgameItemUserData{itemId=8001,itemCount=0x100000003L};f.Manager.OnSave();Require(f.Backend.Writes==0,"real login gate not bypassed");f.Host.Progress=10;f.Global.Indexes.Items[8001].itemCount++;f.Manager.OnSave();Require(f.Backend.Writes==1,"changed state writes after explicitly configured test login");var restarted=new Fixture(f.Backend);Require(restarted.Manager.GetItemNum(8001)==0x100000004L&&restarted.Global.Data.saveTimestamp==OutgameItemTimestamp.FromDateTime(restarted.Now),"Int64 record restores through actual storage and global lifecycle");});
            check("source-item-manager-server-download-gate-and-current-global",()=>{var f=new Fixture();var old=f.Global;f.Host.Server=true;f.Manager.UpdateData(true);Require(f.Downloads==1&&ReferenceEquals(old,f.Global),"download request, no implicit callback");f.Manager.ParticipatesInSync=false;f.Manager.UpdateData(true);Require(f.Downloads==1,"autosyn false reads local");var replacement=new OutgameGlobalItemLifecycle(f.GlobalHost,()=>{},id=>true,id=>true,()=>f.Now);f.Global=replacement;f.Manager.UpdateDataCallBack("{\"itemUserDatas\":[{\"itemId\":8001,\"itemCount\":9}],\"productUserDatas\":[]}");Require(f.Manager.GetItemNum(8001)==9&&ReferenceEquals(replacement,f.Global),"every callback/count resolves current global");});
