            check("source-item-manager-reward-filter-truncation-and-live-list",()=>{var f=new Fixture();var rewards=new List<OutgameItemReward>{new OutgameItemReward{itemId=8001,itemCount=3},new OutgameItemReward{itemId=1001,itemCount=0x100000002L}};f.Effects.Saving=()=>{if(rewards.Count==2)rewards.Add(new OutgameItemReward{itemId=1002,itemCount=4});};f.Manager.AddRewards(rewards);Require(f.Local.goldNum==2&&f.Local.diamondsNum==4&&string.Join(",",f.Effects.Trace)=="save,save"&&f.Trace.Count==0,"type6 skip, signed low32, live loop, refresh/report false");f.Manager.ExpendReward(null);f.Manager.Update();});
            check("source-item-manager-reward-save-failure-keeps-prefix",()=>{var f=new Fixture();f.Effects.Saving=()=>throw new InvalidOperationException();Throws<InvalidOperationException>(()=>f.Manager.AddRewards(new List<OutgameItemReward>{new OutgameItemReward{itemId=1001,itemCount=3},new OutgameItemReward{itemId=1002,itemCount=4}}));Require(f.Local.goldNum==3&&f.Local.diamondsNum==0,"no atomic rollback or continuation");});
            check("source-item-manager-package-rewards-drain-shares-rows",()=>{var f=new Fixture();var row=new OutgameItemReward{itemId=3,itemCount=9};var held=f.Manager.PackageOpenRewardsTemp;held.AddLast(row);held.AddLast(row);var rewards=f.Manager.GetPackageOpenReward();Require(rewards.Count==2&&ReferenceEquals(rewards[0],row)&&ReferenceEquals(held,f.Manager.PackageOpenRewardsTemp)&&held.Count==0&&f.Manager.GetPackageOpenReward().Count==0,"copy list, shared row references, clear same linked list");});
            check("source-item-factory-all-source-subtype-mappings",()=>{var f=new Fixture();var cases=new[]{new[]{1,1,4496},new[]{1,2,4494},new[]{1,4,4499},new[]{1,5,4493},new[]{1,8,4498},new[]{1,10,4497},new[]{1,11,4495},new[]{9,1,4490},new[]{9,2,4491}};int seen=0;foreach(var c in cases){f.ConfigSlot.Instance.Items[8001]=new GameItemConfig{id=8001,type1=c[0],type2=c[1]};f.Construct=(t,id)=>{Require(t==c[2]&&id==8001,"exact original source type");seen++;return new Entity();};Require(f.Manager.GetItem(new GameItemConfig{id=8001,type1=99})!=null,"input config supplies id only; factory rereads current table");}Require(seen==9,"all supported types");foreach(var c in new[]{new[]{4,1},new[]{1,3},new[]{1,6},new[]{1,7},new[]{1,9},new[]{9,3}}){f.ConfigSlot.Instance.Items[8001]=new GameItemConfig{id=8001,type1=c[0],type2=c[1]};Require(f.Manager.GetItem(f.ConfigSlot.Instance.Items[8001])==null,"source unsupported subtype returns null");}});
