            check("source-item-module-rejects-negative-and-overflow-before-factory",()=>{var f=new Fixture();Require(!f.Control.ChangeItemNum(8001,-1)&&f.Trace.Count==0&&f.Warnings[0]=="道具 8001 数量不足!!!","insufficient balance no effects");f.Global.Indexes.Items[8001]=new OutgameItemUserData{itemId=8001,itemCount=long.MaxValue};Require(!f.Control.ChangeItemNum(8001,1)&&f.Trace.Count==0,"unchecked Int64 overflow rejected as negative");});
