            check("source-item-module-real-gold-entity-global-local-and-storage-chain",()=>{var f=new Fixture();f.Host.Progress=10;f.ConfigSlot.Instance.Items[1001]=new GameItemConfig{id=1001,type1=1,type2=1};var reports=new OutgameGlobalItemRewardsValidation.Reports();var engine=new OutgameGlobalItemRewards(f.Global,()=>f.ConfigSlot.Instance,()=>f.Messages,()=>reports,f.Warnings.Add);var services=new OutgameItemEntityServices{Config=()=>f.ConfigSlot.Instance,Rewards=()=>engine,Messages=()=>f.Messages,Reports=()=>reports};f.Construct=services.Construct;Require(f.Control.ChangeItemNum(1001,7)&&f.Global.GetItemCount(1001)==7&&f.Local.goldNum==7&&f.Backend.Writes==1&&reports.Changes.Count==1,"real module -> manager -> factory -> Gold -> global -> manager -> Tool/local -> pool/storage");Require(f.Control.ChangeItemNum(1001,-3)&&f.Global.GetItemCount(1001)==4&&f.Local.goldNum==4&&f.Backend.Writes==2&&!reports.Gains[1],"real debit and report flow");var restored=new Fixture(f.Backend);Require(restored.Global.GetItemCount(1001)==4,"shared record reload includes real entity mutations");});
